-- Migration 031: One-way member blocking and suppressed-message retention.
-- Target: MariaDB 10.1.38. Apply manually after a backup.
-- PURGE_AT is set by application code only for messages suppressed by blocking.

CREATE TABLE IF NOT EXISTS ALUMNI_MEMBER_BLOCK (
    AMB_SEQ          BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    BLOCKER_USR_SEQ  INT NOT NULL,
    BLOCKED_USR_SEQ  INT NOT NULL,
    CREATED_AT       DATETIME NOT NULL,
    UPDATED_AT       DATETIME NOT NULL,
    UNIQUE KEY UK_AMB_DIRECTION (BLOCKER_USR_SEQ, BLOCKED_USR_SEQ),
    INDEX IDX_AMB_BLOCKED (BLOCKED_USR_SEQ, BLOCKER_USR_SEQ)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE ALUMNI_MESSAGE
    ADD COLUMN AM_CLIENT_MESSAGE_ID VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
    ADD COLUMN AM_VISIBLE_RECVR ENUM('Y','N') NOT NULL DEFAULT 'Y',
    ADD COLUMN AM_SUPPRESSION_REASON VARCHAR(30) NULL,
    ADD COLUMN PURGE_AT DATETIME NULL;

ALTER TABLE ALUMNI_MESSAGE
    ADD UNIQUE KEY UK_AM_SENDER_CLIENT (AM_SENDER_SEQ, AM_CLIENT_MESSAGE_ID),
    ADD INDEX IDX_AM_RECVR_VISIBLE (AM_RECVR_SEQ, AM_VISIBLE_RECVR, REG_DATE),
    ADD INDEX IDX_AM_PURGE (PURGE_AT);
